from collections.abc import Iterable, Mapping
from copy import deepcopy


class PlantingLedger:
    _required = {"field", "crop", "planting_date"}
    _optional = {"variety", "notes", "tags"}

    def __init__(self):
        self._records = []
        self._next_id = 1

    @classmethod
    def _normalize(cls, record):
        if not isinstance(record, Mapping):
            raise TypeError("each record must be a mapping")
        keys = set(record)
        missing = cls._required - keys
        unknown = keys - cls._required - cls._optional
        if missing:
            raise ValueError("missing required fields")
        if unknown:
            raise ValueError("unknown fields are not permitted")

        normalized = dict(record)
        for key in cls._required | {"variety", "notes"}:
            value = normalized.get(key, "")
            if not isinstance(value, str):
                raise TypeError(f"{key} must be a string")
            if key in cls._required and not value.strip():
                raise ValueError(f"{key} must not be empty")
            normalized[key] = value

        tags = normalized.get("tags", [])
        if not isinstance(tags, list) or any(not isinstance(tag, str) for tag in tags):
            raise TypeError("tags must be a list of strings")
        normalized["tags"] = tags
        return normalized

    def add(self, record):
        normalized = self._normalize(record)
        stored = {"id": self._next_id, **normalized}
        self._records.append(stored)
        self._next_id += 1
        return deepcopy(stored)

    def import_records(self, records):
        if isinstance(records, (str, bytes)) or not isinstance(records, Iterable):
            raise TypeError("records must be a non-string iterable")
        normalized_batch = [self._normalize(record) for record in records]
        added = []
        for normalized in normalized_batch:
            stored = {"id": self._next_id, **normalized}
            self._records.append(stored)
            self._next_id += 1
            added.append(deepcopy(stored))
        return added

    def all_records(self):
        return deepcopy(self._records)

